// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(address a0, address a1, uint256 amt0, uint256 amt1) public {
        vm.assume(a0 != a1);
        vm.assume(a0 != address(this) && a1 != address(this));
        vm.assume(amt0 > 0 && amt1 > 0);
        vm.assume(amt0 <= type(uint256).max / 2 && amt1 <= type(uint256).max / 2);

        vm.deal(a0, amt0);
        vm.prank(a0);
        (bool okDep0,) = address(c).call{value: amt0}("");
        require(okDep0);

        vm.deal(a1, amt1);
        vm.prank(a1);
        (bool okDep1,) = address(c).call{value: amt1}("");
        require(okDep1);

        vm.prank(a0);
        c.withdraw();

        vm.prank(a1);
        bool ok;
        try c.withdraw() { ok = true; } catch { ok = false; }

        assertTrue(ok);
    }
}
